select t2.drugname from ( select patient.uniquepid, treatment.treatmenttime, patient.patienthealthsystemstayid from treatment join patient on treatment.patientunitstayid = patient.patientunitstayid where patient.patienthealthsystemstayid in ( select patient.patienthealthsystemstayid from patient where patient.uniquepid = '005-66412' ) and treatment.treatmentname = 'vte prophylaxis - compression stockings' and strftime('%y-%m',treatment.treatmenttime) <= '2105-09' ) as t1 join ( select patient.uniquepid, medication.drugname, medication.drugstarttime, patient.patienthealthsystemstayid from medication join patient on medication.patientunitstayid = patient.patientunitstayid where patient.patienthealthsystemstayid in ( select patient.patienthealthsystemstayid from patient where patient.uniquepid = '005-66412' ) and strftime('%y-%m',medication.drugstarttime) <= '2105-09' ) as t2 on t1.uniquepid = t2.uniquepid where t1.treatmenttime < t2.drugstarttime and t1.patienthealthsystemstayid = t2.patienthealthsystemstayid	eicu
