select sum( case when patient.hospitaldischargestatus = 'alive' then 1 when strftime('%j',patient.hospitaldischargetime) - strftime('%j',t2.diagnosistime) > 2 * 365 then 1 else 0 end ) * 100 / count(*) from ( select t1.uniquepid, t1.diagnosistime from ( select patient.uniquepid, diagnosis.diagnosistime from diagnosis join patient on diagnosis.patientunitstayid = patient.patientunitstayid where diagnosis.diagnosisname = 'sepsis - sepsis with single organ dysfunction- metabolic encephalopathy' group by patient.uniquepid having min(diagnosis.diagnosistime) = diagnosis.diagnosistime ) as t1 where strftime('%j',current_time) - strftime('%j',t1.diagnosistime) > 2 * 365 ) as t2 join patient on t2.uniquepid = patient.uniquepid	eicu
